1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.server.http.HttpHeader;
5	import net.officefloor.server.http.ServerHttpConnection;
6	import net.officefloor.web.ObjectResponse;
7	import org.springframework.http.ResponseEntity;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	
13	/**
14	 * First step of the create pipeline: honours the optional {@code Idempotency-Key} request header so a
15	 * repeated create returns the originally created owner (200) instead of storing a duplicate (which
16	 * the identity/household checks would otherwise reject with 409).
17	 *
18	 * <p>When the header is present and already maps to a live owner (see {@link IdempotencyStore}), the
19	 * stored owner is sent back with 200 and the {@code create} flow is not taken — short-circuiting the
20	 * rest of the pipeline. Otherwise (no header, or a first-seen key) the {@code create} flow runs the
21	 * normal pipeline; {@link RecordIdempotencyKey} then records the key against the new owner so a later
22	 * repeat resolves here. A key whose stored owner has since been soft-deleted is treated as unseen, so
23	 * the create proceeds afresh.
24	 */
25	public class CheckIdempotencyKey {
26	
27	    /** Header carrying the client-chosen idempotency token; matched case-insensitively. */
28	    static final String HEADER = "Idempotency-Key";
29	
30	    public void service(ServerHttpConnection connection, IdempotencyStore idempotencyStore,
31	            OwnerRepository ownerRepository, OwnerMapper ownerMapper,
32	            @Flow("create") CreateFlow create, ObjectResponse<ResponseEntity<OwnerDto>> response) {
33	        String key = key(connection);
34	        if (key != null) {
35	            Integer ownerId = idempotencyStore.lookup(key);
36	            if (ownerId != null) {
37	                Owner owner = ownerRepository.findById(ownerId);
38	                if (owner != null && !owner.isDeleted()) {
39	                    // Idempotent repeat: return the originally created owner with 200 and stop here.
40	                    OwnerDto dto = ownerMapper.toOwnerDto(owner);
41	                    dto.setBulkSignupWarning(BulkSignup.warningFor(ownerRepository));
42	                    Integer possibleDuplicateOf = PossibleDuplicate.matchFor(owner, ownerRepository);
43	                    dto.setPossibleDuplicate(possibleDuplicateOf != null);
44	                    dto.setPossibleDuplicateOf(possibleDuplicateOf);
45	                    response.send(ResponseEntity.ok(dto));
46	                    return;
47	                }
48	            }
49	        }
50	        // Not a repeat: run the normal create pipeline.
51	        create.create();
52	    }
53	
54	    /** The trimmed {@code Idempotency-Key} value, or {@code null} when absent or blank. */
55	    static String key(ServerHttpConnection connection) {
56	        HttpHeader header = connection.getRequest().getHeaders().getHeader(HEADER);
57	        if (header == null) {
58	            return null;
59	        }
60	        String value = header.getValue();
61	        if (value == null || value.isBlank()) {
62	            return null;
63	        }
64	        return value.trim();
65	    }
66	}
